message.content:
{
  "candidate_edge_types": [
    {
      "name": "USES_CONFIRMED_RESULT_TO_APPLY_SOLUTION",
      "definition": "An observation from an exploratory execution that confirms a candidate technique produces a desired effect is used as the basis for applying that technique to the target solution.",
      "source_description": "An earlier execution observation confirming that a candidate technique or payload achieves the desired effect.",
      "target_description": "A subsequent agent action that applies the confirmed technique to construct or deploy the final solution artifact."
    },
    {
      "name": "VERIFIES_SOLUTION_BY_EXECUTING_TEST",
      "definition": "A subsequent agent action executes a test or validation procedure to determine whether a constructed or modified solution satisfies the task requirements.",
      "source_description": "A constructed or modified solution artifact produced by the agent.",
      "target_description": "An execution of a test or validation procedure intended to check the solution."
    },
    {
      "name": "DIAGNOSES_FAILURE_CAUSE",
      "definition": "An observed execution failure or unexpected absence of output leads the agent to analyze and identify the root cause of the failure.",
      "source_description": "An observed execution failure or unexpected result.",
      "target_description": "A subsequent agent diagnostic analysis identifying the underlying cause."
    },
    {
      "name": "ADAPTS_TO_UNAVAILABLE_TOOL",
      "definition": "A failure caused by a required tool or command being unavailable leads the agent to select an alternative method for performing the intended operation.",
      "source_description": "An observed failure caused by unavailability of a required tool or command.",
      "target_description": "A subsequent agent action that uses an alternative method to accomplish the intended operation."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "RETRIES_OPERATION_AFTER_REPAIRING_CAUSE",
      "definition": "After taking action to repair the cause of an earlier failure, the agent repeats the previously failed operation.",
      "source_description": "An earlier failed operation.",
      "target_description": "A repeated execution of that operation after the cause of the failure has been addressed."
    },
    {
      "name": "USES_DIAGNOSIS_TO_SELECT_REPAIR_ACTION",
      "definition": "A diagnostic conclusion about the cause of a failure determines the specific corrective action taken next.",
      "source_description": "A diagnostic analysis identifying the root cause of a failure.",
      "target_description": "A subsequent repair action selected to address that root cause."
    },
    {
      "name": "COMPLETES_TASK_AFTER_SUCCESSFUL_VERIFICATION",
      "definition": "A successful verification result leads the agent to decide that the task is complete and to signal task completion.",
      "source_description": "A verification result indicating that the solution satisfies the requirements.",
      "target_description": "A subsequent task-completion decision or action."
    }
  ]
}

